# Code generated by "go run ./cmd/gensdkpy" in the exe.dev repository. DO NOT EDIT.

"""The wire format, shared by the sync and async clients: command lines,
responses, and the NDJSON stream of a command's output."""

from __future__ import annotations

import base64
import binascii
import codecs
import json
import os
import re
import shlex
from collections.abc import Awaitable, Callable, Coroutine, Generator, Iterable, Mapping, Sequence
from dataclasses import dataclass
from datetime import datetime
import functools
from contextlib import AbstractAsyncContextManager
from typing import Any, Generic, Literal, ParamSpec, TypeVar, cast

import httpx

from ._errors import (
    CommandInterruptedError,
    OutputLimitError,
    ProtocolError,
    is_error_document,
)
from .types import RmResponse

DEFAULT_BASE_URL = "https://exe.dev"

# Commands other than ssh end within the server's own timeout (30s; cp's is
# 5.5 minutes), so a read that waits longer than this is a dead connection.
# An ssh stream sends a blank line every 30s while its command is quiet.
READ_TIMEOUT = 600.0
CONNECT_TIMEOUT = 30.0
TIMEOUT = httpx.Timeout(READ_TIMEOUT, connect=CONNECT_TIMEOUT)

HEADERS = {
    "Content-Type": "text/plain",
    "Accept": "application/json, application/x-ndjson",
}

MAX_OUTPUT = 8 * 1024 * 1024
# Output frames carry one write each, which is small; refuse an unbounded
# frame even when not capturing.
MAX_FRAME = 1024 * 1024

Flag = tuple[str, str, Any]
"""A command-line flag: name, kind (bool, number, string, or repeated), and value. None omits it."""
Arg = str | int | Sequence[str] | None
"""A positional argument, or several (variadic), or None for an omitted optional one."""


def command_line(path: str, args: Sequence[Arg], flags: Iterable[Flag] = ()) -> str:
    """The exe.dev command line for path, args, and flags, quoted for its shell-like parser."""
    words = [path]
    for name, kind, value in flags:
        if value is None:
            continue
        if kind == "bool":
            words.append(f"--{name}" if value else f"--{name}=false")
        elif kind == "repeated":
            words.extend(f"--{name}={shlex.quote(v)}" for v in _strings(name, value))
        else:
            words.append(f"--{name}={shlex.quote(_word(name, value))}")
    positionals: list[str] = []
    skipped = False
    for arg in args:
        if arg is None:
            skipped = True
            continue
        for a in _strings(path, arg):
            if skipped:
                raise TypeError(f"{path}: an argument follows an omitted one")
            positionals.append(a)
    if any(p.startswith("-") for p in positionals):
        words.append("--")
    words.extend(shlex.quote(p) for p in positionals)
    return " ".join(words)


def _word(name: str, value: object) -> str:
    if isinstance(value, str):
        return value
    if isinstance(value, int) and not isinstance(value, bool):
        return str(value)
    raise TypeError(f"{name}: expected a string or an integer, not {type(value).__name__}")


def _strings(name: str, value: object) -> list[str]:
    # A string is iterable, but it is one value, not one per character.
    if isinstance(value, (str, int)) and not isinstance(value, bool):
        return [_word(name, value)]
    if isinstance(value, Iterable):
        return [_word(name, v) for v in cast(Iterable[object], value)]
    raise TypeError(f"{name}: expected strings, not {type(value).__name__}")


def required(name: str, values: Sequence[str]) -> Sequence[str]:
    """values, a variadic argument that needs at least one."""
    if not values:
        raise TypeError(f"expected at least one {name}")
    return values


def on_off(value: bool | None) -> str | None:
    """The on|off argument for value."""
    return None if value is None else "on" if value else "off"


def env_flags(env: object) -> list[str] | None:
    """KEY=VALUE for each environment variable in env."""
    if env is None:
        return None
    if not isinstance(env, Mapping):
        raise TypeError("env must be a mapping of names to values")
    out = []
    for key, value in cast(Mapping[object, object], env).items():
        if not isinstance(key, str) or not key or "=" in key or not isinstance(value, str):
            raise TypeError("env must map names (without =) to strings")
        out.append(f"{key}={value}")
    return out


_ENV_NAME = re.compile(r"[A-Za-z_][A-Za-z0-9_]*\Z")


def ssh_command(
    command: str | Sequence[str], cwd: str | os.PathLike[str] | None = None, env: Mapping[str, str] | None = None
) -> str:
    """A shell command line: command itself, or an argument list quoted for
    the shell; run in cwd, with env exported."""
    if isinstance(command, str):
        line = command
    else:
        words = list(command)
        if not words or not all(isinstance(w, str) for w in words):
            raise TypeError("command must be a string or a nonempty sequence of strings")
        line = shlex.join(words)
    prefix = []
    if cwd is not None:
        path = os.fspath(cwd)
        if not isinstance(path, str) or not path:
            raise TypeError("cwd must be a nonempty path")
        # A command must not run in the wrong directory.
        prefix.append(f"cd {shlex.quote(path)} || exit")
    if env is not None:
        if not isinstance(env, Mapping):
            raise TypeError("env must be a mapping of names to values")
        for key, value in cast(Mapping[object, object], env).items():
            if not isinstance(key, str) or not _ENV_NAME.match(key) or not isinstance(value, str):
                raise TypeError("env must map variable names to strings")
            prefix.append(f"export {key}={shlex.quote(value)}")
    return "; ".join([*prefix, line])


_VM_NAME = re.compile(r"[a-zA-Z0-9][a-zA-Z0-9-]*\Z")


def vm_name(name: object) -> str:
    """name, validated as a VM name."""
    if not isinstance(name, str):
        raise TypeError(f"expected a VM name, not {type(name).__name__}")
    if not _VM_NAME.match(name):
        raise ValueError(f"{name!r} is not a VM name")
    return name


@dataclass(frozen=True)
class CommandResult:
    """How a command run with VM.run() ended, and what it wrote."""

    exit_code: int
    """The command's exit status; 128+N if it was killed by signal N, as in a shell."""
    stdout_bytes: bytes = b""
    stderr_bytes: bytes = b""
    captured: bool = True
    """Whether output was captured. With run(capture=False), stdout and stderr are empty."""

    @property
    def stdout(self) -> str:
        """Standard output as text. Invalid UTF-8 becomes U+FFFD; stdout_bytes has the bytes."""
        return self.stdout_bytes.decode(errors="replace")

    @property
    def stderr(self) -> str:
        """Standard error as text. Invalid UTF-8 becomes U+FFFD; stderr_bytes has the bytes."""
        return self.stderr_bytes.decode(errors="replace")

    @property
    def ok(self) -> bool:
        """Whether the command exited with status 0."""
        return self.exit_code == 0


Stream = Literal["stdout", "stderr"]


class Output:
    """Reads the NDJSON body of an ssh command: output frames in, output out.

    Each line is one JSON object with one key: stdout or stderr (base64
    bytes), then exit_code, or error in place of an exit code. Blank lines
    are heartbeats.
    """

    def __init__(self, capture: bool, max_output: int) -> None:
        if not isinstance(capture, bool):
            raise TypeError("capture must be a bool")
        if not isinstance(max_output, int) or isinstance(max_output, bool) or max_output < 0:
            raise TypeError("max_output must be a nonnegative int")
        self.capture = capture
        self.max_output = max_output
        self.exit_code: int | None = None
        self._chunks: dict[Stream, list[bytes]] = {"stdout": [], "stderr": []}
        self._count = 0
        self._buffer = bytearray()
        self._decoders = {
            "stdout": codecs.getincrementaldecoder("utf-8")(errors="replace"),
            "stderr": codecs.getincrementaldecoder("utf-8")(errors="replace"),
        }

    def feed(self, data: bytes) -> list[tuple[Stream, bytes]]:
        """Read a chunk of the body; return the output it completes."""
        self._buffer += data
        out: list[tuple[Stream, bytes]] = []
        start = 0
        while (end := self._buffer.find(b"\n", start)) >= 0:
            if (frame := self._frame(bytes(self._buffer[start:end]))) is not None:
                out.append(frame)
            start = end + 1
        del self._buffer[:start]
        if len(self._buffer) > MAX_FRAME:
            raise ProtocolError("ssh")
        return out

    def finish(self) -> list[tuple[Stream, bytes]]:
        """Read the end of the body. Raises if it did not end with an exit code."""
        frame = self._frame(bytes(self._buffer))
        self._buffer.clear()
        if self.exit_code is None:
            raise self.interrupted()
        return [frame] if frame is not None else []

    def text(self, stream: Stream, data: bytes, final: bool = False) -> str:
        """Decode data, which continues stream's output, as text."""
        return self._decoders[stream].decode(data, final)

    def interrupted(
        self, cls: type[CommandInterruptedError] = CommandInterruptedError, *args: str, reason: str | None = None
    ) -> CommandInterruptedError:
        """An exception carrying the output captured so far."""
        return cls(
            *args,
            captured=self.capture,
            stdout=b"".join(self._chunks["stdout"]),
            stderr=b"".join(self._chunks["stderr"]),
            reason=reason,
        )

    def result(self) -> CommandResult:
        assert self.exit_code is not None
        return CommandResult(
            self.exit_code, b"".join(self._chunks["stdout"]), b"".join(self._chunks["stderr"]), self.capture
        )

    def _frame(self, line: bytes) -> tuple[Stream, bytes] | None:
        if not line.strip():
            return None
        if self.exit_code is not None or len(line) > MAX_FRAME:
            raise ProtocolError("ssh")
        try:
            frame = json.loads(line)
        except ValueError:
            raise ProtocolError("ssh") from None
        if not isinstance(frame, dict) or len(frame) != 1:
            raise ProtocolError("ssh")
        ((key, value),) = cast(dict[str, object], frame).items()
        if key in ("stdout", "stderr") and isinstance(value, str):
            stream = cast(Stream, key)
            try:
                data = base64.b64decode(value, validate=True)
            except binascii.Error:
                raise ProtocolError("ssh") from None
            if self.capture:
                if self._count + len(data) > self.max_output:
                    raise self.interrupted(OutputLimitError, "the command's output exceeded max_output")
                self._count += len(data)
                self._chunks[stream].append(data)
            return stream, data
        if key == "exit_code" and isinstance(value, int) and not isinstance(value, bool) and value >= 0:
            self.exit_code = value
            return None
        if key == "error" and isinstance(value, str):
            raise self.interrupted(reason=value)
        raise ProtocolError("ssh")


def is_ndjson(response: httpx.Response) -> bool:
    content_type: str = response.headers.get("Content-Type", "")
    return content_type.split(";")[0].strip().lower() == "application/x-ndjson"


def stream_timeout(remaining: float | None) -> httpx.Timeout:
    """Timeouts for an ssh request that must end within remaining seconds."""
    if remaining is None:
        return TIMEOUT
    remaining = max(remaining, 0.001)
    return httpx.Timeout(min(READ_TIMEOUT, remaining), connect=min(CONNECT_TIMEOUT, remaining))


@dataclass
class VMInfo:
    """What the SDK knows about a VM."""

    name: str
    tags: tuple[str, ...] = ()
    status: str | None = None
    ssh_dest: str | None = None
    https_url: str | None = None
    region: str | None = None
    comment: str | None = None
    created_at: datetime | None = None
    prompt_error: str | None = None


def vm_info(value: object, operation: Literal["new", "ls", "cp"]) -> VMInfo:
    """A VM from new's, ls's, or cp's JSON. cp names its fields differently."""
    if not isinstance(value, dict):
        raise ProtocolError(operation)
    obj = cast(dict[str, object], value)

    def string(key: str, required: bool = False) -> str | None:
        v = obj.get(key)
        if v is None and not required:
            return None
        if not isinstance(v, str) or (required and not v):
            raise ProtocolError(operation)
        return v

    cp = operation == "cp"
    name = string("name" if cp else "vm_name", True)
    if name is None or not _VM_NAME.match(name):
        raise ProtocolError(operation)
    tags = obj.get("tags") or []
    if not isinstance(tags, list) or not all(isinstance(t, str) for t in cast(list[object], tags)):
        raise ProtocolError(operation)
    created = string("created_at")
    try:
        created_at = datetime.fromisoformat(created) if created else None
    except ValueError:
        raise ProtocolError(operation) from None
    return VMInfo(
        name=name,
        tags=tuple(cast(list[str], tags)),
        status=string("state" if cp else "status"),
        ssh_dest=string("ssh" if cp else "ssh_dest", True),
        https_url=string("https_url", not cp),
        region=string("region"),
        comment=string("comment"),
        created_at=created_at,
        prompt_error=string("error"),
    )


def vm_list(value: object) -> list[VMInfo]:
    """The VMs in ls's JSON."""
    vms = value.get("vms") if isinstance(value, dict) else None
    if not isinstance(vms, list):
        raise ProtocolError("ls")
    return [vm_info(row, "ls") for row in cast(list[object], vms)]


def rm_result(docs: list[Any] | None) -> RmResponse:
    """rm's summary, among the error documents it reports per VM."""
    summary = [d for d in docs or [] if not is_error_document(d)]

    def strings(v: object) -> bool:
        return isinstance(v, list) and all(isinstance(s, str) for s in cast(list[object], v))

    obj = summary[0] if len(summary) == 1 and isinstance(summary[0], dict) else None
    if (
        obj is None
        or not strings(obj.get("deleted"))
        or not strings(obj.get("failed"))
        or ("not_found" in obj and not strings(obj["not_found"]))
        or ("errors" in obj and not _string_map(obj["errors"]))
    ):
        raise ProtocolError("rm")
    return cast(RmResponse, obj)


def _string_map(v: object) -> bool:
    return isinstance(v, dict) and all(isinstance(s, str) for s in cast(dict[object, object], v).values())


# Retry readiness probes that /exec rejected before a remote command started.
RETRYABLE = re.compile(r"failed to (?:connect|dial|create session|run command on VM)", re.IGNORECASE)

# Report exe-setup.service's state, whether a setup script is in place, and
# on failure the end of its journal. exe-init puts /exe.dev/setup in place
# before exessh answers, and the unit removes it once it has run. exessh can
# answer before exe-init hands PID 1 to systemd, and then before systemd's
# bus is up ("Failed to connect to bus"): both are "booting".
SETUP_PROBE = """\
if [ -e /exe.dev/setup ]; then echo Setup=present; else echo Setup=absent; fi
if [ ! -d /run/systemd/system ]; then
  if [ -e /etc/systemd/system/exe-setup.service ]; then echo State=booting; else echo State=unsupported; fi
  exit 0
fi
props=$(systemctl show exe-setup.service -p LoadState -p ActiveState -p Job -p Result -p ExecMainCode \
-p ExecMainStatus -p ExecMainExitTimestampMonotonic -p ConditionResult -p ConditionTimestampMonotonic \
2>/dev/null) || { echo State=booting; exit 0; }
echo "$props"
echo "SystemState=$(systemctl is-system-running 2>/dev/null)"
if [ "$(systemctl show exe-setup.service -p ActiveState --value)" = failed ]; then
  echo ---
  journalctl -b -u exe-setup.service -o cat --no-pager -n 50 2>&1
fi"""


@dataclass(frozen=True)
class SetupFailure:
    """The arguments to VMSetupError, which needs a VM."""

    result: str
    exit_code: int | None = None
    signal: int | None = None
    output: str = ""


def setup_state(output: str) -> Literal["pending", "done"] | SetupFailure:
    """Parse SETUP_PROBE's output. "done" covers success and having no setup script to wait for."""
    head, *journal = output.split("\n---\n")
    p: dict[str, str] = {}
    for line in head.split("\n"):
        key, sep, value = line.partition("=")
        if sep and key:
            p[key] = value.strip()

    def number(key: str) -> int | None:
        v = p.get(key, "")
        return int(v) if v.isascii() and v.isdigit() else None

    if p.get("Setup") not in ("present", "absent"):
        raise ProtocolError("ssh setup probe")
    script = p["Setup"] == "present"
    state = p.get("State")
    # Early in boot, the unit cannot have run yet: without a script it has nothing to run.
    if state == "booting":
        return "pending" if script else "done"
    if state == "unsupported" or p.get("LoadState") == "not-found":
        return SetupFailure("unsupported") if script else "done"
    active = p.get("ActiveState")
    if not p.get("LoadState") or not active:
        raise ProtocolError("ssh setup probe")
    if active in ("activating", "deactivating", "reloading"):
        return "pending"
    if active == "failed" or (number("ExecMainExitTimestampMonotonic") and p.get("Result") != "success"):
        # ExecMainCode: 1 exited, 2 killed, 3 dumped core. ExecMainStatus is the code or signal.
        code, status = number("ExecMainCode"), number("ExecMainStatus")
        return SetupFailure(
            p.get("Result") or "failed",
            status if code == 1 else None,
            status if code in (2, 3) else None,
            "\n---\n".join(journal),
        )
    if number("ExecMainExitTimestampMonotonic"):
        return "done"
    if number("ConditionTimestampMonotonic") and p.get("ConditionResult") == "no":
        return "done"
    # The unit has not run this boot. With no script, it has nothing to run:
    # a restart need not wait for boot to reach it.
    if not script:
        return "done"
    # Not reached yet while the system boots; otherwise it is not going to run.
    if p.get("Job") not in (None, "", "0") or p.get("SystemState") in ("initializing", "starting"):
        return "pending"
    return SetupFailure("not-run")


def check_ready(wait_until: object, timeout: float | None) -> None:
    """Validate readiness arguments before creating, copying, or restarting a VM."""
    if wait_until != "created":
        ready_timeout(wait_until, timeout)


def ready_timeout(until: object, timeout: float | None) -> float:
    """The readiness deadline in seconds, validated before anything is created."""
    if until not in ("ssh", "setup"):
        raise ValueError('wait_until must be "ssh", "setup", or "created"')
    if timeout is None:
        return 600.0 if until == "setup" else 60.0
    if isinstance(timeout, bool) or not isinstance(timeout, (int, float)) or not timeout > 0:
        raise ValueError("timeout must be a positive number of seconds")
    return float(timeout)


_P = ParamSpec("_P")
_VM = TypeVar("_VM", bound=AbstractAsyncContextManager[Any])


class Creating(Awaitable[_VM], Generic[_VM]):
    """A VM on its way: await it, or use it as an async context manager to
    delete the VM at the end of the block::

        async with exe.new() as vm:
            ...
    """

    def __init__(self, creation: Coroutine[Any, Any, _VM]) -> None:
        self._creation = creation
        self._vm: _VM | None = None

    def __await__(self) -> Generator[Any, None, _VM]:
        return self._creation.__await__()

    async def __aenter__(self) -> _VM:
        self._vm = await self._creation
        return cast(_VM, await self._vm.__aenter__())

    async def __aexit__(self, *exc: Any) -> None:
        assert self._vm is not None
        await self._vm.__aexit__(*exc)


def creates(method: Callable[_P, Coroutine[Any, Any, _VM]]) -> Callable[_P, Creating[_VM]]:
    """Make an async method that creates a VM return a Creating."""

    @functools.wraps(method)
    def wrapper(*args: _P.args, **kwargs: _P.kwargs) -> Creating[_VM]:
        return Creating(method(*args, **kwargs))

    return wrapper
